'use strict';
let offlineVoices=[],offlineVoiceReady=false,offlineVoiceBusy=false,offlineVoiceContext=null,offlineVoiceCache=null;
document.body.insertAdjacentHTML('beforeend',`<dialog id="offlineVoiceDialog"><div class="tool-heading"><div><div class="eyebrow">VOICE-OVER</div><h2>Create voice-over</h2></div><button id="closeOfflineVoice">Close</button></div><p class="note"><span id="voiceProviderNote">Local voices run on your PC. ElevenLabs voices use your internet connection and account credits, including previews.</span></p><textarea id="offlineVoiceText" rows="5" aria-label="Voice-over text"></textarea><div class="offline-voice-settings"><label>Voice<select id="offlineVoiceChoice"></select></label><label>Pace<select id="offlineVoiceSpeed"><option value="0.8">Slower</option><option value="0.9">Narrator pace</option><option value="1" selected>Natural pace</option><option value="1.2">Faster</option></select></label><label>Style<select id="offlineVoiceDelivery"><option value="natural">Natural</option><option value="narrator">Narrator</option><option value="bright">Bright</option><option value="gentle">Gentle</option><option value="serious">Serious</option></select></label></div><p class="note">Style adjusts pace and pauses. Acting depends on the selected voice; preview before adding.</p><audio id="offlineVoiceAudio" controls hidden></audio><label><input id="offlineVoiceLipSync" type="checkbox" checked> Add lip-sync for the speaking character</label><p id="offlineVoiceStatus" role="status" class="note">Checking local voice tools…</p><div class="tool-row"><button id="previewOfflineVoice">Preview voice</button><button id="addOfflineVoice" class="primary">Add to dialogue</button></div></dialog>`);
async function openOfflineVoice(line){stop();offlineVoiceContext={project,scene:current(),line};const opened=offlineVoiceContext;offlineVoiceReady=false;for(const id of ['previewOfflineVoice','addOfflineVoice'])$(id).disabled=true;offlineVoiceCache=null;$('offlineVoiceText').value=line.text;const initialActor=current().objects.find(o=>o.id===line.speakerId);$('offlineVoiceDelivery').value=line.ttsDelivery||initialActor?.ttsDelivery||(!line.speakerId?project.narratorDelivery:null)||'natural';$('offlineVoiceSpeed').value=String(line.ttsSpeed||(line.speakerId?1:.9));$('offlineVoiceAudio').hidden=true;$('offlineVoiceAudio').removeAttribute('src');$('offlineVoiceLipSync').disabled=!line.speakerId;$('offlineVoiceLipSync').checked=!!line.speakerId;$('offlineVoiceLipSync').closest('label').hidden=!line.speakerId;$('offlineVoiceStatus').textContent='Checking local voices…';$('offlineVoiceDialog').showModal();try{const r=await fetch('/api/voices',{cache:'no-store'});if(!r.ok)throw Error('Local voice service is not available in this app version.');const data=await r.json();if(offlineVoiceContext!==opened||!$('offlineVoiceDialog').open)return;offlineVoices=data.voices||[];offlineVoiceReady=!!data.available;const select=$('offlineVoiceChoice');select.replaceChildren();for(const v of offlineVoices){const o=document.createElement('option');o.value=v.id;o.textContent=v.name;select.append(o)}const actor=current().objects.find(o=>o.id===line.speakerId),index=Math.max(0,storyActors(current()).indexOf(actor));select.value=line.ttsVoice||actor?.ttsVoice||(!line.speakerId?project.narratorVoice||offlineVoices[Math.min(3,offlineVoices.length-1)]?.id:null)||offlineVoices[index%Math.max(1,offlineVoices.length)]?.id||'';$('offlineVoiceStatus').textContent=offlineVoiceReady?data.kokoro?'Ready. Piper and Kokoro voices are installed on this PC.':'Ready. Voice files are already on this PC.':'The local voice engine is still being installed. Reopen this window when it is ready.'}catch(e){if(offlineVoiceContext!==opened||!$('offlineVoiceDialog').open)return;offlineVoiceReady=false;$('offlineVoiceStatus').textContent=e.message}for(const id of ['previewOfflineVoice','addOfflineVoice'])$(id).disabled=!offlineVoiceReady}
function offlineVoiceRequest(){const text=$('offlineVoiceText').value.trim();if(!text)throw Error('Write the dialogue first.');return{text,voice:$('offlineVoiceChoice').value,speed:+$('offlineVoiceSpeed').value,delivery:$('offlineVoiceDelivery').value}}
async function synthesizeOfflineVoice(){const request=offlineVoiceRequest(),key=JSON.stringify(request);if(offlineVoiceCache?.key===key)return offlineVoiceCache;$('offlineVoiceStatus').textContent=request.voice.startsWith('elevenlabs:')?'Creating the voice with ElevenLabs · uses account credits…':'Creating the voice locally…';const response=await fetch('/api/tts',{method:'POST',headers:{'Content-Type':'application/json'},body:key});if(!response.ok){const error=await response.json();throw Error(error.error||'Voice generation failed.')}const blob=await response.blob(),buffer=await decodeFile(blob);if(buffer.duration>60)throw Error('This line is longer than 60 seconds. Split it into shorter turns.');const src=await dataURL(blob);offlineVoiceCache={key,request,src,buffer};$('offlineVoiceAudio').src=src;$('offlineVoiceAudio').hidden=false;$('offlineVoiceStatus').textContent='Voice ready · '+buffer.duration.toFixed(1)+' seconds.';return offlineVoiceCache}
async function offlineVoiceTask(task){if(offlineVoiceBusy||storyProcessing||speechProcessing||recording)return;offlineVoiceBusy=speechProcessing=true;window.editorTaskBusy=true;const frozen=[...$('offlineVoiceDialog').querySelectorAll('button,input,select,textarea')].map(e=>[e,e.disabled]);frozen.forEach(([e])=>e.disabled=true);try{await task()}catch(e){$('offlineVoiceStatus').textContent=e.message}finally{offlineVoiceBusy=speechProcessing=false;window.editorTaskBusy=false;frozen.forEach(([e,disabled])=>e.disabled=disabled)}}
$('previewOfflineVoice').onclick=()=>offlineVoiceTask(async()=>{await synthesizeOfflineVoice();$('offlineVoiceAudio').play().catch(()=>{})});
$('addOfflineVoice').onclick=()=>offlineVoiceTask(async()=>{const context=offlineVoiceContext;if(project!==context?.project||current()!==context.scene||!storyLines(current()).includes(context.line))throw Error('The script changed. Open the voice tool again.');const l=context.line,actor=current().objects.find(o=>o.id===l.speakerId);if(actor?.locked||ownedStoryVoice(l)?.locked)throw Error('Unlock the speaking character and its voice first.');if(tracks().length>=99&&!ownedStoryVoice(l))throw Error('Keep fewer than 100 audio clips.');const voice=await synthesizeOfflineVoice();if(project!==context.project)throw Error('The project changed. Open this line again.');removeStoryVoice(l);const c={id:uid(),name:actorName(current(),l.speakerId)+' · '+voice.request.text.slice(0,45),role:'narration',start:storySceneOffset(current())+l.start,offset:0,duration:voice.buffer.duration,sourceDuration:voice.buffer.duration,volume:1,src:voice.src,tts:{engine:offlineVoices.find(v=>v.id===voice.request.voice)?.engine||'piper',voice:voice.request.voice,speed:voice.request.speed,delivery:voice.request.delivery}};tracks().push(c);audioBuffers.set(c.id,voice.buffer);l.text=voice.request.text;l.audioId=c.id;l.duration=c.duration;l.ttsVoice=voice.request.voice;l.ttsSpeed=voice.request.speed;l.ttsDelivery=voice.request.delivery;if(actor){actor.ttsVoice=voice.request.voice;actor.ttsDelivery=voice.request.delivery}else{project.narratorVoice=voice.request.voice;project.narratorDelivery=voice.request.delivery}current().dialogueArranged=false;save();const arranged=arrangeConversation();if($('offlineVoiceLipSync').checked&&actor){$('offlineVoiceStatus').textContent='Voice added. Creating mouth timing locally…';const response=await fetch('/api/lipsync',{method:'POST',headers:{'Content-Type':'audio/wav'},body:sourceAudioSlice(c)}),result=await response.json();if(!response.ok)throw Error('Voice was added; mouth timing failed: '+(result.error||'try Lip-sync voices again.'));c.mouthCues=result.mouthCues.filter(m=>Number.isFinite(m.start)&&Number.isFinite(m.end)&&m.end>=m.start&&/^[A-HX]$/.test(m.value));actor.lipSync=true;save();render()}
 renderStoryEditor();$('offlineVoiceAudio').pause();$('offlineVoiceStatus').textContent=arranged?'Voice added to the conversation. It will mix with your timeline audio.':'Voice created. Split or shorten the conversation, then arrange it.';toast('Local voice added to dialogue.');$('offlineVoiceDialog').close()});
$('closeOfflineVoice').onclick=()=>{if(!offlineVoiceBusy)$('offlineVoiceDialog').close()};$('offlineVoiceDialog').addEventListener('cancel',e=>{if(offlineVoiceBusy)e.preventDefault()});$('offlineVoiceDialog').addEventListener('close',()=>$('offlineVoiceAudio').pause());
const voiceMetadataValidator=valid;valid=function(p){return voiceMetadataValidator(p)&&p.scenes.every(s=>storyLines(s).every(l=>(l.ttsVoice===undefined||typeof l.ttsVoice==='string'&&l.ttsVoice.length<=100)&&(l.ttsSpeed===undefined||Number.isFinite(l.ttsSpeed)&&l.ttsSpeed>=.6&&l.ttsSpeed<=1.6)&&(l.ttsDelivery===undefined||['natural','narrator','bright','gentle','serious'].includes(l.ttsDelivery))))};
